        object url = add(add(getValue(getValue(this.urls, "api"), "rest"), "/"), this.implodeParams(path, parameters));
        object query = this.omit(parameters, this.extractParams(path));
        headers = new Dictionary<string, object>() {};
        if (isTrue(isEqual(api, "private")))
        {
            // wallex authenticates with the raw key in x-api-key, there is no secret and no hmac signature
            this.checkRequiredCredentials();
            ((IDictionary<string,object>)headers)["X-API-KEY"] = this.apiKey;
        }
        if (isTrue(isEqual(method, "GET")))
        {
            if (isTrue(isGreaterThan(getArrayLength(new List<object>(((IDictionary<string,object>)query).Keys)), 0)))
            {
                url = add(url, add("?", this.urlencode(query)));
            }
        } else
        {
            body = this.json(query);
            ((IDictionary<string,object>)headers)["Content-Type"] = "application/json";
        }
        return new Dictionary<string, object>() {
            { "url", url },
            { "method", method },
            { "body", body },
            { "headers", headers },
        };
    }

